1	package vae
2	
3	import (
4		"context"
5		"fmt"
6		"math"
7		"time"
8		"unsafe"
9	
10		"strix-halo-vulkan/shaders"
11		"strix-halo-vulkan/vk"
12	)
13	
14	// The decoder on the device — IMAGE.md Q5g, the stage that stood between
15	// Q4's 2.27 s DiT step and a served image.
16	//
17	// The CPU decoder in vae.go is the oracle and is also the reason this file
18	// exists: it decodes 256x256 in ~20 s, and the graph is 16x larger at
19	// 1024x1024, so a served generation would have spent minutes downstream of
20	// a 91 s transformer.
21	//
22	// Almost none of it is new. z-image's decoder graph (zimage/vae/gpu.go)
23	// established the shape — one weight arena written once, one activation
24	// arena a bump allocator ping-pongs inside, "which tensor" as an offset
25	// rather than a descriptor rebind, and the whole decode recorded as a
26	// dispatch list — and its kernels do the work here unchanged: the
27	// register-blocked fp32 convolution, the 2x nearest upsample, the add, and
28	// the mid block's row-major attention with its transposed K. Three things
29	// in this VAE are genuinely not in that one, and each is one shader:
30	//
31	//   - the norm. RMS_norm here is a per-pixel L2 normalize across channels,
32	//     not a group norm, and it is always followed by a SiLU — qvae_chnorm
33	//     does both in one pass;
34	//   - the up blocks' parameter-free channel-to-space shortcut, whose
35	//     channel mapping depends on a video model's temporal factor even
36	//     though no temporal axis survives at T = 1 — qvae_dupup;
37	//   - the mid block is 1152 channels wide where z-image's is 512, which the
38	//     scalar attention kernel needs as a compile-time bound.
39	//
40	// The mid block's four projections are 1x1 convolutions, which is to say
41	// linears over the pixel rows, and to_qkv's [3C, C] weight is three of them
42	// stacked — so the graph reads it at three offsets rather than splitting the
43	// tensor. That is why there is no qkv convolution in the dispatch list.
44	//
45	// Everything here is fp32. Q0 measured this decoder's intermediates at
46	// absmax ~1e5–3e5 against fp16's 65504, so the matrix-core convolution that
47	// took z-image's decode from 3.18 s to 258 ms cannot simply be pointed at
48	// this graph; what it would take is priced in gpu_test.go's range
49	// measurement, and it is Q9's, not Q5g's.
50	
51	// pushConstants mirrors the PC block in shaders/vae_common.glsl. Every
52	// pipeline in the graph declares the same block, because vk.DispatchMultiTimed
53	// records the whole thing into one command buffer and requires one
54	// push-constant size across it.
55	type pushConstants struct {
56		InOff, OutOff    uint32
57		C, H, W          uint32
58		OC, KH, KW, Pad  uint32
59		WOff, BOff       uint32
60		Groups           uint32
61		ResOff           uint32
62		Aux0, Aux1, Aux2 uint32
63		// The GEMM block, unused on this path but part of the layout: the block's
64		// size is fixed by the shaders the graph borrows.
65		GemmB, GemmM, GemmN, GemmK uint32
66		LDA, LDB                   uint32
67	}
68	
69	const noBias = 0xffffffff
70	
71	// dispatchesPerSubmit caps how much work goes into one command buffer. The
72	// whole graph in a single submit trips the driver's reset watchdog and comes
73	// back as VK_ERROR_DEVICE_LOST; the same dispatches submitted in batches all
74	// complete. 4 is z-image's measured-free value and this graph's dispatches
75	// are no larger than that one's.
76	const dispatchesPerSubmit = 4
77	
78	func (p pushConstants) bytes() []byte {
79		out := make([]byte, unsafe.Sizeof(p))
80		*(*pushConstants)(unsafe.Pointer(&out[0])) = p
81		return out
82	}
83	
84	// arena hands out element offsets inside one activation buffer, with a
85	// best-fit free list. It is zimage/vae's, for the reason that file gives:
86	// an up block's input is twice the channel count of what its resnets
87	// produce, so exact-size bucketing fills the arena with large blocks that
88	// can never serve the smaller requests that follow.
89	type arena struct {
90		next uint32
91		high uint32
92		free []freeBlock
93	}
94	
95	type freeBlock struct {
96		off  uint32
97		size uint32
98	}
99	
100	func roundUp(elems int) uint32 { return uint32((elems + 63) &^ 63) }
101	
102	func (a *arena) alloc(elems int) uint32 {
103		n := roundUp(elems)
104		best := -1
105		for i, b := range a.free {
106			if b.size >= n && (best < 0 || b.size < a.free[best].size) {
107				best = i
108			}
109		}
110		if best >= 0 {
111			blk := a.free[best]
112			a.free = append(a.free[:best], a.free[best+1:]...)
113			if rem := blk.size - n; rem >= 64 {
114				a.free = append(a.free, freeBlock{off: blk.off + n, size: rem})
115			}
116			return blk.off
117		}
118		off := a.next
119		a.next += n
120		if a.next > a.high {
121			a.high = a.next
122		}
123		return off
124	}
125	
126	// release returns a block, coalescing with neighbours and giving back to the
127	// bump pointer anything that now ends at it.
128	func (a *arena) release(off uint32, elems int) {
129		blk := freeBlock{off: off, size: roundUp(elems)}
130		for merged := true; merged; {
131			merged = false
132			for i, b := range a.free {
133				if b.off+b.size == blk.off {
134					blk.off, blk.size = b.off, b.size+blk.size
135				} else if blk.off+blk.size == b.off {
136					blk.size += b.size
137				} else {
138					continue
139				}
140				a.free = append(a.free[:i], a.free[i+1:]...)
141				merged = true
142				break
143			}
144		}
145		a.free = append(a.free, blk)
146		for {
147			i := -1
148			for j, b := range a.free {
149				if b.off+b.size == a.next {
150					i = j
151					break
152				}
153			}
154			if i < 0 {
155				return
156			}
157			a.next = a.free[i].off
158			a.free = append(a.free[:i], a.free[i+1:]...)
159		}
160	}
161	
162	func (a *arena) reset() {
163		a.next = 0
164		a.free = nil
165	}
166	
167	// gpuWeights is the flat fp32 weight arena plus every tensor's offset in it.
168	type gpuWeights struct {
169		data []float32
170		off  map[string]uint32
171	}
172	
173	func (g *gpuWeights) put(name string, v []float32) {
174		g.off[name] = uint32(len(g.data))
175		g.data = append(g.data, v...)
176	}
177	
178	// midDim is the channel width the attention kernel was built for. The build
179	// is shaders.VAEAttentionDim1152 and the bound is a shared-array extent, so
180	// a checkpoint with a different mid width would silently write past it — it
181	// is refused at load instead.
182	const midDim = 1152
183	
184	// engine is the Vulkan half of a graph on this device: the two buffers, the
185	// pipelines, the flattened weights and the activation arena. The decoder and
186	// the encoder are two graphs over one set of kernels, so this is what they
187	// share — the same split zimage/vae made between its own two directions.
188	type engine struct {
189		dev *vk.Device
190	
191		wbuf *vk.Buffer
192		abuf *vk.Buffer
193	
194		pipes   map[string]*vk.ComputePipeline
195		mods    []*vk.ShaderModule
196		weights *gpuWeights
197	
198		// The two kernels Q9b screened; see kernels.go. Both graphs resolve them
199		// the same way, which is why they live here.
200		conv convVariant
201		mid  midVariant
202	
203		arena arena
204	}
205	
206	// stage uploads the weights, sizes the arena and builds every pipeline.
207	func (e *engine) stage(dev *vk.Device, set map[string][]byte, arenaElems uint32) error {
208		e.dev = dev
209		var err error
210		wbytes := len(e.weights.data) * 4
211		if e.wbuf, err = dev.NewBuffer(wbytes); err != nil {
212			return fmt.Errorf("qvae: weight buffer (%d MB): %w", wbytes>>20, err)
213		}
214		e.wbuf.WriteFloat32(e.weights.data)
215		if e.abuf, err = dev.NewBuffer(int(arenaElems) * 4); err != nil {
216			return fmt.Errorf("qvae: activation buffer (%d MB): %w", (int(arenaElems)*4)>>20, err)
217		}
218		bufs := []*vk.Buffer{e.wbuf, e.abuf}
219		pcSize := uint32(unsafe.Sizeof(pushConstants{}))
220		for name, spirv := range set {
221			mod, err := dev.NewShaderModule(spirv)
222			if err != nil {
223				return fmt.Errorf("qvae: shader %s: %w", name, err)
224			}
225			e.mods = append(e.mods, mod)
226			pipe, err := dev.NewPipeline(mod, vk.PipelineSpec{Buffers: bufs, PushConstantSize: pcSize})
227			if err != nil {
228				return fmt.Errorf("qvae: pipeline %s: %w", name, err)
229			}
230			e.pipes[name] = pipe
231		}
232		return nil
233	}
234	
235	func (e *engine) destroy() {
236		for _, p := range e.pipes {
237			p.Destroy()
238		}
239		for _, m := range e.mods {
240			m.Destroy()
241		}
242		for _, b := range []*vk.Buffer{e.abuf, e.wbuf} {
243			if b != nil {
244				b.Destroy()
245			}
246		}
247		e.pipes, e.mods = map[string]*vk.ComputePipeline{}, nil
248		e.abuf, e.wbuf = nil, nil
249	}
250	
251	// run submits a prefix of a recorded graph, to completion.
252	func (e *engine) run(ds []vk.MultiDispatch) error {
253		return e.runContext(context.Background(), ds)
254	}
255	
256	// runContext is run with a cancellation point, and the batching this graph
257	// already does for the driver's sake is what provides one.
258	//
259	// A submitted command buffer has no cancellation point inside it — the fence
260	// is waited on or the device is left mid-graph — so the finest granularity
261	// available is *between* submits. That is already every four dispatches
262	// (dispatchesPerSubmit, a watchdog constraint rather than a choice), which
263	// puts a 1024² decode's 117 dispatches at 30 batches of ~250 ms. So a client
264	// that hangs up during a decode stops paying for it within a quarter of a
265	// second instead of 7.5 s, and the device lock is released that much sooner
266	// for whoever is queued behind them.
267	//
268	// The error wraps ctx.Err(), so `errors.Is(err, context.Canceled)` holds all
269	// the way up to the handler, which is where it becomes "no answer" rather
270	// than a 500.
271	func (e *engine) runContext(ctx context.Context, ds []vk.MultiDispatch) error {
272		for i := 0; i < len(ds); i += dispatchesPerSubmit {
273			if err := ctx.Err(); err != nil {
274				return fmt.Errorf("qvae: cancelled after %d of %d dispatches: %w", i, len(ds), err)
275			}
276			j := min(i+dispatchesPerSubmit, len(ds))
277			if _, err := vk.DispatchMultiTimed(ds[i:j], 1, 1, true); err != nil {
278				return fmt.Errorf("qvae: dispatch %d-%d: %w", i, j-1, err)
279			}
280		}
281		return nil
282	}
283	
284	// read copies one arena tensor back.
285	func (e *engine) read(t tensor) *Tensor {
286		out := NewTensor(1, t.C, t.H, t.W)
287		copy(out.Data, e.abuf.ReadFloat32At(int(t.off), t.elems()))
288		return out
289	}
290	
291	// ActivationBytes and WeightBytes are what the graph costs in device memory.
292	func (e *engine) ActivationBytes() int { return e.abuf.Size() }
293	func (e *engine) WeightBytes() int     { return e.wbuf.Size() }
294	
295	// newEngine is an engine with its maps made but nothing staged, which is also
296	// what the sizing passes record against. The kernels are the screen's winners
297	// from the start, so that a sizing pass — which never calls chooseKernels,
298	// having no device and no options — records the graph the real one will run.
299	func newEngine() engine {
300		e := engine{
301			pipes:   make(map[string]*vk.ComputePipeline),
302			weights: &gpuWeights{off: make(map[string]uint32)},
303		}
304		if err := e.chooseKernels(Options{}); err != nil {
305			panic(err) // the defaults are constants; this cannot fail at runtime
306		}
307		return e
308	}
309	
310	// GPUDecoder runs the decode graph on a Vulkan device.
311	type GPUDecoder struct {
312		engine
313		cpu *Decoder
314	}
315	
316	// shaderSet is every pipeline the graph uses. Six of the eight are z-image's
317	// unchanged.
318	var shaderSet = map[string][]byte{
319		"conv2d":     shaders.VAEConv2D,
320		"add":        shaders.VAEAdd,
321		"upsample2x": shaders.VAEUpsample2x,
322		"to_rows":    shaders.VAENCHWToRows,
323		"to_nchw":    shaders.VAERowsToNCHWAdd,
324		"linear":     shaders.VAELinear,
325		"transpose":  shaders.VAETranspose,
326		"attention":  shaders.VAEAttentionDim1152,
327		"chnorm":     shaders.QVAEChannelNorm,
328		"dupup":      shaders.QVAEDupUp,
329	}
330	
331	// NewGPUDecoder uploads a loaded decoder's weights, builds its pipelines and
332	// sizes the activation arena for a latentH x latentW latent — which is the
333	// largest the returned decoder will accept, since the arena is allocated
334	// once.
335	func NewGPUDecoder(dev *vk.Device, cpu *Decoder, latentH, latentW int) (*GPUDecoder, error) {
336		return NewGPUDecoderOpts(dev, cpu, latentH, latentW, Options{})
337	}
338	
339	// NewGPUDecoderOpts is NewGPUDecoder with the two screened kernels named,
340	// which is what TestGPUKernelScreen sweeps and what holds the new graph
341	// against the one it replaces.
342	func NewGPUDecoderOpts(dev *vk.Device, cpu *Decoder, latentH, latentW int, opt Options) (*GPUDecoder, error) {
343		if got := cpu.Mid.Attn.QKV.InC; got != midDim {
344			return nil, fmt.Errorf("qvae: mid block is %d channels, the attention kernel is built for %d", got, midDim)
345		}
346		g := &GPUDecoder{engine: newEngine(), cpu: cpu}
347		if err := g.chooseKernels(opt); err != nil {
348			return nil, err
349		}
350		g.flattenWeights()
351	
352		need, err := g.planSize(latentH, latentW)
353		if err != nil {
354			g.Destroy()
355			return nil, err
356		}
357		if err := g.stage(dev, g.kernelSet(shaderSet), need); err != nil {
358			g.Destroy()
359			return nil, err
360		}
361		return g, nil
362	}
363	
364	// Destroy releases every Vulkan object.
365	func (g *GPUDecoder) Destroy() { g.destroy() }
366	
367	// flattenWeights copies every weight the graph reads into one arena, in the
368	// order the graph reads them. to_qkv stays one [3C, C] tensor: the three
369	// projections are its three row blocks, and the graph addresses them by
370	// offset.
371	func (g *GPUDecoder) flattenWeights() {
372		w := g.weights
373		conv := func(name string, c *Conv2D) {
374			w.put(name+".weight", c.Weight)
375			if c.Bias != nil {
376				w.put(name+".bias", c.Bias)
377			}
378		}
379		norm := func(name string, n *ChannelNorm) { w.put(name+".gamma", n.Gamma) }
380		res := func(name string, r *ResBlock) {
381			norm(name+".norm1", &r.Norm1)
382			conv(name+".conv1", &r.Conv1)
383			norm(name+".norm2", &r.Norm2)
384			conv(name+".conv2", &r.Conv2)
385			if r.Shortcut != nil {
386				conv(name+".shortcut", r.Shortcut)
387			}
388		}
389	
390		d := g.cpu
391		conv("post_quant", &d.PostQuant)
392		conv("conv_in", &d.ConvIn)
393		res("mid.r1", &d.Mid.Res1)
394		norm("mid.attn.norm", &d.Mid.Attn.Norm)
395		conv("mid.attn.qkv", &d.Mid.Attn.QKV)
396		conv("mid.attn.proj", &d.Mid.Attn.Proj)
397		res("mid.r2", &d.Mid.Res2)
398		for i := range d.Ups {
399			up := &d.Ups[i]
400			for j := range up.Resnets {
401				res(fmt.Sprintf("up.%d.r%d", i, j), &up.Resnets[j])
402			}
403			if up.Up != nil {
404				conv(fmt.Sprintf("up.%d.upconv", i), &up.Up.Conv)
405			}
406		}
407		norm("norm_out", &d.NormOut)
408		conv("conv_out", &d.ConvOut)
409	}
410	
411	// tensor is a shape plus its offset in the activation arena.
412	type tensor struct {
413		off     uint32
414		C, H, W int
415	}
416	
417	func (t tensor) elems() int { return t.C * t.H * t.W }
418	
419	// builder records a graph into a dispatch list. It is shared by both
420	// directions: the decoder and the encoder differ in what they record, not in
421	// how it is recorded.
422	type builder struct {
423		e     *engine
424		ar    *arena
425		out   []vk.MultiDispatch
426		kinds []string
427		flops []float64
428	
429		pendingKind  string
430		pendingFlops float64
431		pendingIn    tensor
432	
433		// ins is each dispatch's input tensor where one convolution reads one
434		// tensor, and the zero value otherwise. ConvInputRanges is its only
435		// reader: what a matrix-core convolution would need to know about this
436		// graph is whether the operand it narrows fits in fp16, and that is a
437		// property of these tensors.
438		ins []tensor
439	
440		// marks names the tensor each named stage leaves behind and the dispatch
441		// that finishes it. A bump-allocated graph overwrites every intermediate
442		// long before it ends, so the only way to look at one is to re-run the
443		// prefix and stop — which is what RunTo does and what the stagewise gate
444		// in gpu_test.go needs.
445		marks map[string]tensor
446		order []string
447		stops []int
448	
449		err error
450	}
451	
452	func (b *builder) mark(name string, t tensor) tensor {
453		if b.marks != nil {
454			b.marks[name] = t
455			b.order = append(b.order, name)
456			b.stops = append(b.stops, len(b.out))
457		}
458		return t
459	}
460	
461	func (b *builder) label(kind string, flops float64) {
462		b.pendingKind, b.pendingFlops = kind, flops
463	}
464	
465	func groups(n, local int) uint32 { return uint32((n + local - 1) / local) }
466	
467	func (b *builder) add(pipe string, gx uint32, pc pushConstants) {
468		b.addXY(pipe, gx, 1, pc)
469	}
470	
471	func (b *builder) addXY(pipe string, gx, gy uint32, pc pushConstants) {
472		if b.err != nil {
473			return
474		}
475		// planSize records the same graph with no pipelines built, purely to size
476		// the arena, so a missing pipeline is an error only once there are any.
477		p := b.e.pipes[pipe]
478		if p == nil && len(b.e.pipes) > 0 {
479			b.err = fmt.Errorf("qvae: no pipeline %q", pipe)
480			return
481		}
482		b.out = append(b.out, vk.MultiDispatch{Pipeline: p, GroupsX: gx, GroupsY: gy, PushConstants: pc.bytes()})
483		kind := b.pendingKind
484		if kind == "" {
485			kind = pipe
486		}
487		b.kinds = append(b.kinds, kind)
488		b.flops = append(b.flops, b.pendingFlops)
489		b.ins = append(b.ins, b.pendingIn)
490		b.pendingKind, b.pendingFlops, b.pendingIn = "", 0, tensor{}
491	}
492	
493	func (b *builder) release(ts ...tensor) {
494		for _, t := range ts {
495			b.ar.release(t.off, t.elems())
496		}
497	}
498	
499	// wOff resolves a weight. A missing one is an error only once there are
500	// pipelines to dispatch — the same condition as addXY, and for the same
501	// reason: the sizing pass records the graph against neither.
502	func (b *builder) wOff(name string) uint32 {
503		off, ok := b.e.weights.off[name]
504		if !ok && b.err == nil && len(b.e.pipes) > 0 {
505			b.err = fmt.Errorf("qvae: no weight %q", name)
506		}
507		return off
508	}
509	
510	func (b *builder) bOff(name string) uint32 {
511		if off, ok := b.e.weights.off[name]; ok {
512			return off
513		}
514		return noBias
515	}
516	
517	// conv appends a convolution producing a fresh tensor. Both shapes the
518	// decoder uses — 3x3 pad 1 and the 1x1 pad 0 shortcuts and projections —
519	// preserve H and W.
520	func (b *builder) conv(name string, c *Conv2D, x tensor) tensor {
521		out := tensor{off: b.ar.alloc(c.OutC * x.H * x.W), C: c.OutC, H: x.H, W: x.W}
522		b.label(fmt.Sprintf("conv%dx%d %d->%d @%dx%d", c.KH, c.KW, x.C, c.OutC, x.H, x.W),
523			2*float64(c.OutC)*float64(x.H)*float64(x.W)*float64(x.C)*float64(c.KH)*float64(c.KW))
524		b.pendingIn = x
525		// The grid's y axis is output-channel blocks: the shader holds OC_BLOCK
526		// accumulators per thread, which is where its arithmetic intensity is,
527		// and which build supplies it is the screen's answer (kernels.go).
528		pipe, ocBlock := b.e.convPipe(c.OutC)
529		b.addXY(pipe, groups(out.H*out.W, 256), groups(c.OutC, ocBlock), pushConstants{
530			InOff: x.off, OutOff: out.off,
531			C: uint32(x.C), H: uint32(x.H), W: uint32(x.W),
532			OC: uint32(c.OutC), KH: uint32(c.KH), KW: uint32(c.KW), Pad: uint32(c.Pad),
533			WOff: b.wOff(name + ".weight"), BOff: b.bOff(name + ".bias"),
534		})
535		return out
536	}
537	
538	// chnorm appends the channel norm, optionally with its SiLU fused. dst may
539	// be src: one thread owns one pixel's whole channel column, so writing it
540	// back over the read is safe and saves a tensor.
541	func (b *builder) chnorm(name string, silu bool, src, dst tensor) tensor {
542		aux := uint32(0)
543		if silu {
544			aux = 1
545		}
546		b.label(fmt.Sprintf("chnorm %d @%dx%d", src.C, src.H, src.W), 0)
547		b.add("chnorm", groups(src.H*src.W, 256), pushConstants{
548			InOff: src.off, OutOff: dst.off,
549			C: uint32(src.C), H: uint32(src.H), W: uint32(src.W),
550			WOff: b.wOff(name + ".gamma"),
551			Aux0: aux,
552		})
553		return dst
554	}
555	
556	// addInto appends a += res.
557	func (b *builder) addInto(a, res tensor) tensor {
558		b.add("add", groups(a.elems(), 256), pushConstants{
559			InOff: a.off, OutOff: a.off, ResOff: res.off, Aux0: uint32(a.elems()),
560		})
561		return a
562	}
563	
564	// resblock records one residual block. keepIn leaves the input allocated,
565	// which the up blocks need: their parameter-free shortcut reads the block's
566	// input after all three resnets have run.
567	//
568	// Every release happens after the dispatch that consumes the tensor is
569	// recorded and after the next tensor is allocated; releasing earlier would
570	// let the allocator hand the same block to a tensor still being read.
571	func (b *builder) resblock(name string, r *ResBlock, x tensor, keepIn bool) tensor {
572		// norm1 writes into a fresh tensor rather than over x: x is the residual
573		// and is read again at the end of the block.
574		h := tensor{off: b.ar.alloc(x.elems()), C: x.C, H: x.H, W: x.W}
575		b.chnorm(name+".norm1", true, x, h)
576	
577		h1 := b.conv(name+".conv1", &r.Conv1, h)
578		b.release(h)
579		b.chnorm(name+".norm2", true, h1, h1)
580	
581		h2 := b.conv(name+".conv2", &r.Conv2, h1)
582		b.release(h1)
583	
584		skip := x
585		if r.Shortcut != nil {
586			skip = b.conv(name+".shortcut", r.Shortcut, x)
587		}
588		out := b.addInto(h2, skip)
589		if r.Shortcut != nil {
590			b.release(skip)
591		}
592		if !keepIn {
593			b.release(x)
594		}
595		return out
596	}
597	
598	// projection records one of the mid block's four 1x1 projections over the
599	// pixel rows, on whichever kernel the screen chose. Both read the same push
600	// constants — a row-major [rows, inDim] operand, a PyTorch [outDim, inDim]
601	// weight and a bias — and differ only in the grid: one thread per output
602	// element, or one workgroup per 64x64 output tile.
603	func (b *builder) projection(src, dst tensor, h, w, inDim, outDim int, wOff, bOff uint32) {
604		rows := h * w
605		b.label(fmt.Sprintf("linear %d->%d x%d", inDim, outDim, rows),
606			2*float64(rows)*float64(outDim)*float64(inDim))
607		pc := pushConstants{
608			InOff: src.off, OutOff: dst.off,
609			C: uint32(inDim), H: uint32(h), W: uint32(w), OC: uint32(outDim),
610			WOff: wOff, BOff: bOff,
611		}
612		if v := b.e.mid; v.tiled {
613			b.addXY("linear", groups(rows, v.bm), groups(outDim, v.bn), pc)
614			return
615		}
616		b.add("linear", groups(rows*outDim, 64), pc)
617	}
618	
619	// attention records the mid block's single-head spatial attention. The three
620	// projections are the three row blocks of to_qkv's [3C, C] weight, read at
621	// offsets; the output projection is its own 1x1. Both run on vae_linear over
622	// the pixel rows, which is what a 1x1 convolution is once the tensor is
623	// transposed out of NCHW.
624	func (b *builder) attention(name string, a *Attention, x tensor) tensor {
625		rows := x.H * x.W
626		dim := x.C
627	
628		h := tensor{off: b.ar.alloc(x.elems()), C: x.C, H: x.H, W: x.W}
629		b.chnorm(name+".norm", false, x, h)
630	
631		seq := tensor{off: b.ar.alloc(rows * dim), C: dim, H: x.H, W: x.W}
632		b.add("to_rows", groups(rows*dim, 256), pushConstants{
633			InOff: h.off, OutOff: seq.off,
634			C: uint32(dim), H: uint32(x.H), W: uint32(x.W),
635		})
636		b.release(h)
637	
638		qkvW, qkvB := b.wOff(name+".qkv.weight"), b.wOff(name+".qkv.bias")
639		proj := func(which int) tensor {
640			out := tensor{off: b.ar.alloc(rows * dim), C: dim, H: x.H, W: x.W}
641			b.projection(seq, out, x.H, x.W, dim, dim,
642				qkvW+uint32(which*dim*dim), qkvB+uint32(which*dim))
643			return out
644		}
645		q, k, v := proj(0), proj(1), proj(2)
646		b.release(seq)
647	
648		// Transpose K so the score loop reads consecutive keys at consecutive
649		// addresses. The +64 pads the row stride off a multiple of the 4 KB
650		// channel rotation (IDEAS §5.1b).
651		kStride := rows + 64
652		kT := tensor{off: b.ar.alloc(dim * kStride), C: dim, H: 1, W: kStride}
653		b.label(fmt.Sprintf("transpose %dx%d", rows, dim), 0)
654		b.add("transpose", groups(rows*dim, 256), pushConstants{
655			InOff: k.off, OutOff: kT.off,
656			C: uint32(dim), Aux0: uint32(rows), Aux1: uint32(kStride),
657		})
658		b.release(k)
659	
660		ctx := tensor{off: b.ar.alloc(rows * dim), C: dim, H: x.H, W: x.W}
661		// Two passes of q.k plus the weighted sum of v, all over rows x rows.
662		b.label(fmt.Sprintf("attention %d rows x %d", rows, dim),
663			3*2*float64(rows)*float64(rows)*float64(dim))
664		b.add("attention", uint32(rows), pushConstants{
665			InOff: q.off, OutOff: ctx.off, ResOff: kT.off,
666			C:      uint32(dim),
667			Groups: uint32(kStride),
668			Aux0:   uint32(rows), Aux1: math.Float32bits(float32(1 / math.Sqrt(float64(dim)))), Aux2: v.off,
669		})
670		b.release(q, kT, v)
671	
672		outRows := tensor{off: b.ar.alloc(rows * dim), C: dim, H: x.H, W: x.W}
673		b.projection(ctx, outRows, x.H, x.W, dim, dim,
674			b.wOff(name+".proj.weight"), b.bOff(name+".proj.bias"))
675		b.release(ctx)
676	
677		res := tensor{off: b.ar.alloc(x.elems()), C: x.C, H: x.H, W: x.W}
678		// The bias is already in the projection above, so the fused add has none
679		// of its own — and there is no push-constant value that means "unset", so
680		// it is said explicitly.
681		b.add("to_nchw", groups(x.elems(), 256), pushConstants{
682			InOff: outRows.off, OutOff: res.off, ResOff: x.off,
683			C: uint32(x.C), H: uint32(x.H), W: uint32(x.W),
684			Aux0: noBias,
685		})
686		b.release(outRows, x)
687		return res
688	}
689	
690	// upsample is the learned half of an up block's resampling: nearest 2x, then
691	// a 3x3 convolution.
692	func (b *builder) upsample(name string, c *Conv2D, x tensor) tensor {
693		up := tensor{off: b.ar.alloc(x.C * x.H * 2 * x.W * 2), C: x.C, H: x.H * 2, W: x.W * 2}
694		b.add("upsample2x", groups(up.elems(), 256), pushConstants{
695			InOff: x.off, OutOff: up.off,
696			C: uint32(x.C), H: uint32(x.H), W: uint32(x.W),
697		})
698		b.release(x)
699		out := b.conv(name, c, up)
700		b.release(up)
701		return out
702	}
703	
704	// dupup is the parameter-free shortcut around an up block.
705	func (b *builder) dupup(u *DupUp, x tensor) tensor {
706		out := tensor{off: b.ar.alloc(u.Out * x.H * 2 * x.W * 2), C: u.Out, H: x.H * 2, W: x.W * 2}
707		b.label(fmt.Sprintf("dupup %d->%d @%dx%d", u.In, u.Out, out.H, out.W), 0)
708		b.add("dupup", groups(out.elems(), 256), pushConstants{
709			InOff: x.off, OutOff: out.off,
710			C: uint32(u.In), H: uint32(x.H), W: uint32(x.W), OC: uint32(u.Out),
711			Aux0: uint32(u.FactorT),
712		})
713		return out
714	}
715	
716	// build records the whole decode and returns the output tensor, which is
717	// still unclamped: the clamp to [-1, 1] rides on the readback.
718	func (b *builder) build(d *Decoder, latentH, latentW int) tensor {
719		z := tensor{off: b.ar.alloc(d.PostQuant.InC * latentH * latentW), C: d.PostQuant.InC, H: latentH, W: latentW}
720		x := b.conv("post_quant", &d.PostQuant, z)
721		b.release(z)
722		h := b.conv("conv_in", &d.ConvIn, x)
723		b.release(x)
724		b.mark("conv_in", h)
725	
726		h = b.resblock("mid.r1", &d.Mid.Res1, h, false)
727		h = b.attention("mid.attn", &d.Mid.Attn, h)
728		h = b.resblock("mid.r2", &d.Mid.Res2, h, false)
729		b.mark("mid_block", h)
730	
731		for i := range d.Ups {
732			up := &d.Ups[i]
733			in := h
734			keep := up.Shortcut != nil
735			for j := range up.Resnets {
736				// Only the first resnet reads the block's input, so only it has to
737				// be told to keep it alive.
738				h = b.resblock(fmt.Sprintf("up.%d.r%d", i, j), &up.Resnets[j], h, keep && j == 0)
739			}
740			if up.Up != nil {
741				h = b.upsample(fmt.Sprintf("up.%d.upconv", i), &up.Up.Conv, h)
742			}
743			if up.Shortcut != nil {
744				short := b.dupup(up.Shortcut, in)
745				h = b.addInto(h, short)
746				b.release(short, in)
747			}
748			b.mark(fmt.Sprintf("up_blocks.%d", i), h)
749		}
750	
751		h = b.chnorm("norm_out", true, h, h)
752		b.mark("nonlinearity", h)
753		out := b.conv("conv_out", &d.ConvOut, h)
754		b.release(h)
755		return b.mark("conv_out", out)
756	}
757	
758	// plan records the graph. A nil-pipelined decoder records it purely to size
759	// the arena or count the dispatches.
760	func (g *GPUDecoder) plan(ar *arena, latentH, latentW int, marks bool) (*builder, tensor, error) {
761		b := &builder{e: &g.engine, ar: ar}
762		if marks {
763			b.marks = map[string]tensor{}
764		}
765		out := b.build(g.cpu, latentH, latentW)
766		return b, out, b.err
767	}
768	
769	// MaxStorageBufferBytes is this device's `maxStorageBufferRange`, 4 GiB - 4.
770	// The activation arena is one buffer, so it is also the ceiling on what a
771	// decode can be planned for — see ArenaBytes.
772	const MaxStorageBufferBytes = 4<<30 - 4
773	
774	// ArenaBytes is how much activation memory a decode of this latent would
775	// need, without a device and without loading a weight. It is what sizes the
776	// ceiling Q6's geometry has to respect: the arena is a single storage
777	// buffer, and this device caps one of those at MaxStorageBufferBytes.
778	func ArenaBytes(cpu *Decoder, latentH, latentW int) (int, error) {
779		g := &GPUDecoder{engine: newEngine(), cpu: cpu}
780		n, err := g.planSize(latentH, latentW)
781		if err != nil {
782			return 0, err
783		}
784		return int(n) * 4, nil
785	}
786	
787	// planSize finds how large the activation arena has to be, by recording the
788	// graph with no pipelines bound.
789	func (g *GPUDecoder) planSize(latentH, latentW int) (uint32, error) {
790		saved := g.pipes
791		g.pipes = map[string]*vk.ComputePipeline{}
792		b, _, err := g.plan(&arena{}, latentH, latentW, false)
793		g.pipes = saved
794		if err != nil {
795			return 0, err
796		}
797		return b.ar.high, nil
798	}
799	
800	// Dispatches is the number of GPU dispatches one decode records.
801	func (g *GPUDecoder) Dispatches(latentH, latentW int) (int, error) {
802		saved := g.pipes
803		g.pipes = map[string]*vk.ComputePipeline{}
804		b, _, err := g.plan(&arena{}, latentH, latentW, false)
805		g.pipes = saved
806		if err != nil {
807			return 0, err
808		}
809		return len(b.out), nil
810	}
811	
812	// record builds the graph against the real arena and uploads the latent.
813	func (g *GPUDecoder) record(z *Tensor, marks bool) (*builder, tensor, error) {
814		if z.N != 1 {
815			return nil, tensor{}, fmt.Errorf("qvae: the GPU decoder takes one latent at a time, got N=%d", z.N)
816		}
817		if z.C != g.cpu.PostQuant.InC {
818			return nil, tensor{}, fmt.Errorf("qvae: latent has %d channels, post_quant_conv takes %d", z.C, g.cpu.PostQuant.InC)
819		}
820		g.arena.reset()
821		b, out, err := g.plan(&g.arena, z.H, z.W, marks)
822		if err != nil {
823			return nil, tensor{}, err
824		}
825		if int(b.ar.high)*4 > g.abuf.Size() {
826			return nil, tensor{}, fmt.Errorf("qvae: graph needs %d MB of activations, arena is %d MB",
827				(int(b.ar.high)*4)>>20, g.abuf.Size()>>20)
828		}
829		// The latent is the arena's first allocation, so it goes in at offset 0.
830		g.abuf.WriteFloat32(z.Data)
831		return b, out, nil
832	}
833	
834	// Decode decodes one denormalized latent, clamped to [-1, 1] like the
835	// reference's. The whole graph is recorded once and submitted in batches.
836	func (g *GPUDecoder) Decode(ctx context.Context, z *Tensor) (*Tensor, error) {
837		b, out, err := g.record(z, false)
838		if err != nil {
839			return nil, err
840		}
841		if err := g.runContext(ctx, b.out); err != nil {
842			return nil, err
843		}
844		img := g.read(out)
845		// The clamp is the reference's, and it is free here: the readback is
846		// already walking every element.
847		for i, v := range img.Data {
848			if v > 1 {
849				img.Data[i] = 1
850			} else if v < -1 {
851				img.Data[i] = -1
852			}
853		}
854		return img, nil
855	}
856	
857	// Stages names the graph's marked stages, in order. They are the same names
858	// the CPU decoder's Tap emits, so a stagewise comparison needs no mapping.
859	func (g *GPUDecoder) Stages(latentH, latentW int) ([]string, error) {
860		saved := g.pipes
861		g.pipes = map[string]*vk.ComputePipeline{}
862		b, _, err := g.plan(&arena{}, latentH, latentW, true)
863		g.pipes = saved
864		if err != nil {
865			return nil, err
866		}
867		return b.order, nil
868	}
869	
870	// RunTo re-runs the graph from the start and stops after the named stage,
871	// returning what it produced. A bump-allocated graph overwrites every
872	// intermediate long before it ends, so re-running the prefix is the only way
873	// to see one — the same facility, for the same reason, as zimage/vae's
874	// GPUEncoder.RunTo.
875	func (g *GPUDecoder) RunTo(z *Tensor, stage string) (*Tensor, error) {
876		b, _, err := g.record(z, true)
877		if err != nil {
878			return nil, err
879		}
880		t, ok := b.marks[stage]
881		if !ok {
882			return nil, fmt.Errorf("qvae: no stage %q (have %v)", stage, b.order)
883		}
884		stop := 0
885		for i, name := range b.order {
886			if name == stage {
887				stop = b.stops[i]
888				break
889			}
890		}
891		if err := g.run(b.out[:stop]); err != nil {
892			return nil, err
893		}
894		return g.read(t), nil
895	}
896	
897	// ConvInputRange is one convolution's input magnitude, as measured by
898	// running the graph up to it.
899	type ConvInputRange struct {
900		Index  int
901		Kind   string
902		AbsMax float64
903	}
904	
905	// ConvInputRanges reports, for every convolution in the graph, the largest
906	// magnitude in the tensor it reads.
907	//
908	// It answers the one question standing between this decode and z-image's
909	// matrix-core convolution, which took that operator from 3.18 s to 258 ms
910	// and is 69% of this one. That kernel narrows its B operand — the
911	// activation — to fp16 and accumulates in fp32, so what decides whether it
912	// can be pointed at a graph is whether the activations clear 65504. In
913	// z-image's decoder they peak at 497, 132x inside; Q0 measured this model's
914	// intermediates at absmax ~1e5–3e5, which is why the answer is measured
915	// here rather than inherited.
916	//
917	// It reads a tensor back per convolution over a write-combined buffer, so
918	// it is slow by construction and belongs at the reference latent size.
919	func (g *GPUDecoder) ConvInputRanges(z *Tensor) ([]ConvInputRange, error) {
920		b, _, err := g.record(z, false)
921		if err != nil {
922			return nil, err
923		}
924		var out []ConvInputRange
925		for i := range b.out {
926			if in := b.ins[i]; in.C != 0 {
927				var absMax float64
928				for _, v := range g.abuf.ReadFloat32At(int(in.off), in.elems()) {
929					if a := math.Abs(float64(v)); a > absMax {
930						absMax = a
931					}
932				}
933				out = append(out, ConvInputRange{Index: i, Kind: b.kinds[i], AbsMax: absMax})
934			}
935			if _, err := vk.DispatchMultiTimed(b.out[i:i+1], 1, 1, true); err != nil {
936				return out, fmt.Errorf("qvae: dispatch %d (%s): %w", i, b.kinds[i], err)
937			}
938		}
939		return out, nil
940	}
941	
942	// Stage is one dispatch's identity and cost, as returned by Profile.
943	type Stage struct {
944		Index int
945		Kind  string
946		GPU   time.Duration
947		// Flops is the dispatch's multiply-accumulate count, x2.
948		Flops float64
949	}
950	
951	// Profile runs the graph one dispatch at a time, timing each on the GPU.
952	// Submitting separately costs a fence wait per dispatch, so the total is
953	// above what Decode measures — what it is for is the distribution.
954	func (g *GPUDecoder) Profile(z *Tensor) ([]Stage, error) {
955		b, _, err := g.record(z, false)
956		if err != nil {
957			return nil, err
958		}
959		stages := make([]Stage, 0, len(b.out))
960		for i, d := range b.out {
961			dur, err := d.Pipeline.DispatchTimed(d.GroupsX, d.GroupsY, 1, 1, d.PushConstants)
962			if err != nil {
963				return stages, fmt.Errorf("qvae: dispatch %d (%s): %w", i, b.kinds[i], err)
964			}
965			stages = append(stages, Stage{Index: i, Kind: b.kinds[i], GPU: dur, Flops: b.flops[i]})
966		}
967		return stages, nil
968	}
969

