			if x, err = s.Blocks[i].Apply(x); err != nil {
				return nil, err
			}
			tap(idx, x)
			idx++
		}
		if s.Up != nil {
			x = UpsampleNearest2x(x)
			tap(idx, x)
			if x, err = s.Up.Apply(x); err != nil {
				return nil, err
			}
			tap(idx+1, x)
			idx += 2
		}
	}
	if x, err = d.ConvOut.Apply(x); err != nil {
		return nil, err
	}
	tap(idx, x)
	return TinyToImage(x)
}

