// named; "" is the default.
func NewTinyGPUDecoderKernel(dev *vk.Device, cpu *TinyDecoder, latentH, latentW int, k TinyKernel) (*TinyGPUDecoder, error) {
	if k == "" {
		k = DefaultTinyKernel
