	d := loadTiny(t)
	z := loadTinyRef(t, m, "crop_latent")
	want := loadTinyRef(t, m, "crop_image")

	t.Run("shuffle transposed", func(t *testing.T) {
		var pre *Tensor
		if _, err := d.Decode(z, func(layer int, x *Tensor) {
			if layer == 19 {
				pre = x
			}
		}); err != nil {
