// tinyDiff is the max abs difference and the reference's absmax.
func tinyDiff(t *testing.T, name string, got, want *Tensor) (maxAbs, absMax float64) {
	t.Helper()
	if got.C != want.C || got.H != want.H || got.W != want.W {
